contract InvMutTest {
    C c;
    constructor() { c = new C(0, "", ""); }
    function __ESBMC_reverted() internal returns (bool) {}
    function __ESBMC_assume(bool) internal pure {}
    function run(address from, uint256 amount) public {
        require(amount <= c.balanceOf(address(this)));
        uint256 supplyBefore = c.totalSupply(); if (__ESBMC_reverted()) return;
        uint256 selfBalBefore = c.balanceOf(address(this)); if (__ESBMC_reverted()) return;
        uint256 zeroBalBefore = c.balanceOf(address(0)); if (__ESBMC_reverted()) return;
        bool reverted;
        c.transfer(address(0), amount); bool __rev0 = __ESBMC_reverted(); if (__rev0) { reverted = true; } else { reverted = false; }
        assert(reverted && c.totalSupply() == supplyBefore && c.balanceOf(address(this)) == selfBalBefore && c.balanceOf(address(0)) == zeroBalBefore);
    }
    receive() external payable {}
}

