// SPDX-License-Identifier: UNLICENSED
pragma solidity ^0.8.0;

import {Test} from "forge-std/Test.sol";
import {ERCDDAToken} from "../src/ERCDDAToken.sol";

contract InvMutTest is Test {
    uint256 internal constant VALUE_CAP = 1000000000000000000000000000000;
    ERCDDAToken c;

    function setUp() public {
        c = new ERCDDAToken(0, "", "");
    }

    function _run(address from, uint256 amount) internal {
        vm.assume(amount <= c.balanceOf(address(this)));
        uint256 supplyBefore;
        try c.totalSupply() returns (uint256 __r) { supplyBefore = __r; } catch { return; }
        uint256 selfBalBefore;
        try c.balanceOf(address(this)) returns (uint256 __r) { selfBalBefore = __r; } catch { return; }
        uint256 zeroBalBefore;
        try c.balanceOf(address(0)) returns (uint256 __r) { zeroBalBefore = __r; } catch { return; }
        bool reverted;
        try c.transfer(address(0), amount) { reverted = false; }
        catch { reverted = true; }
        assertTrue(reverted && c.totalSupply() == supplyBefore && c.balanceOf(address(this)) == selfBalBefore && c.balanceOf(address(0)) == zeroBalBefore);
    }

    function testFuzz_run(address from, uint256 amount) public {
        vm.assume(from.code.length == 0 && uint160(from) > 0xffff && from != address(this) && from != address(c) && from != 0x7109709ECfa91a80626fF3989D68f67F5b1DD12D && from != 0x000000000000000000636F6e736F6c652e6c6f67 && from != 0x4e59b44847b379578588920cA78FbF26c0B4956C && from != 0x1804c8AB1F12E6bbf3894d4083f33e07309d1f38);
        _run(from, amount);
    }

    receive() external payable {}
}
